package studio.folio.user;
import studio.folio.security.JwtService;import jakarta.validation.Valid;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt;public AuthController(UserRepository users,PasswordEncoder passwords,JwtService jwt){this.users=users;this.passwords=passwords;this.jwt=jwt;}public record Register(@NotBlank @Size(min=2,max=60) String name,@Email @NotBlank String email,@Size(min=8,max=100) String password){}public record Login(@Email @NotBlank String email,@NotBlank String password){}@PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){String email=r.email().toLowerCase().trim();if(users.existsByEmail(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists");AppUser u=new AppUser();u.name=r.name().trim();u.email=email;u.passwordHash=passwords.encode(r.password());users.save(u);return session(u);}@PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r){AppUser u=users.findByEmail(r.email().toLowerCase().trim()).filter(x->passwords.matches(r.password(),x.passwordHash)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect"));return session(u);}private Map<String,Object> session(AppUser u){return Map.of("token",jwt.issue(u.id,u.email),"user",Map.of("id",u.id,"name",u.name,"email",u.email,"premium",u.premium,"emailVerified",u.emailVerified));}@GetMapping("/me") public Map<String,Object> me(java.security.Principal p){AppUser u=users.findById(p.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return Map.of("id",u.id,"name",u.name,"email",u.email,"premium",u.premium,"emailVerified",u.emailVerified);}}

